import requests
ik='AHOMMSYIKUVNON-UHFFFAOYSA-N'
urls={
'pubchem_cid':f'https://pubchem.ncbi.nlm.nih.gov/rest/pug/compound/inchikey/{ik}/cids/JSON',
'chembl_exact':f'https://www.ebi.ac.uk/chembl/api/data/molecule.json?molecule_structures__standard_inchi_key={ik}&format=json'
}
for k,u in urls.items():
 try:
  r=requests.get(u,timeout=15)
  print(k, r.status_code, r.text[:1500])
 except Exception as e: print(k,type(e).__name__,str(e))

